ch05g-the-guessing-game#9:
secret = 7
guesses = 0
won = False
while guesses < 5 and not won:
    try:
        guess = int(input("Guess: "))
    except ValueError:
        print("Please type a whole number.")
        continue
    guesses = guesses + 1
    if guess > secret:
        print("Too high.")
    elif guess < secret:
        print("Too low.")
    else:
        won = True
if won:
    print("Correct! Guesses: " + str(guesses))
else:
    print("Out of guesses. It was " + str(secret) + ".")

