def is_vowel(letter):
    if letter == "a" or letter == "e" or letter == "i":
        return True
    if letter == "o" or letter == "u":
        return True
    return False


def count_vowels(word):
    vowels = 0
    for character in word:
        if is_vowel(character) == True:
            vowels = vowels + 1
    return vowels

ch06e-splitting-into-functions#9:
def is_prime(number):
    if number < 2:
        return False
    prime = True
    divisor = 2
    while divisor < number:
        if number % divisor == 0:
            prime = False
            break
        divisor = divisor + 1
    return prime


for candidate in range(50):
    if is_prime(candidate):
        print(candidate)

ch07e-asking-and-sorting#9:
def average(numbers):
    if numbers == []:
        return 0
    total = sum(numbers)
    count = len(numbers)
    return total / count

ch07f-looping-over-a-list#9:
def positions(items, target):
    found = []
    for i in range(len(items)):
        if items[i] == target:
            found.append(i)
    return found
